const DEFAULT_DISPLAY_LOCALE = 'en';

type ResolveDisplayLocaleOptions = {
  acceptedLanguages?: readonly string[];
  systemLocale?: string;
};

const canonicalLocale = (candidate: string | undefined): string | null => {
  if (!candidate) return null;
  try {
    return Intl.getCanonicalLocales(candidate)[0] ?? null;
  } catch {
    return null;
  }
};

export const resolveDisplayLocale = (
  options: ResolveDisplayLocaleOptions = {},
): string => {
  const systemLocale =
    options.systemLocale ?? Intl.DateTimeFormat().resolvedOptions().locale;
  const candidates = [
    ...(options.acceptedLanguages ?? []),
    systemLocale,
    DEFAULT_DISPLAY_LOCALE,
  ];
  return (
    candidates.map(canonicalLocale).find((locale) => locale !== null) ??
    DEFAULT_DISPLAY_LOCALE
  );
};
